SELECT  FROM mes_production_defect WHERE 
AND execution_id=#{executionId}
AND affected_node_id=#{affectedNodeId}
AND EXISTS (SELECT 1 FROM mes_production_execution e WHERE e.id=execution_id AND e.workorder_id=#{workorderId})
ORDER BY id DESC

